import re, glob, os
files = glob.glob('static/src/**/*.ts', recursive=True)
# only non-test
files = [f for f in files if not f.endswith('.test.ts')]
deps = {}
for f in files:
    deps[f] = set()
    with open(f) as fh:
        for line in fh:
            m = re.search(r"from\s+'(\./[^']+|../[^']+)'", line)
            if m:
                imp = m.group(1)
                # resolve relative
                base = os.path.dirname(f)
                resolved = os.path.normpath(os.path.join(base, imp))
                if not resolved.endswith('.ts'):
                    resolved += '.ts'
                if resolved in deps or True:
                    deps[f].add(resolved)
# detect cycles among modules (simple)
# Build adjacency
adj = {f: deps[f] for f in files}
# find cycles via DFS
cycles = []
seen=set()
def dfs(node, path, pathset):
    for nb in adj.get(node, ()):
        if nb not in adj: 
            continue
        if nb in pathset:
            idx = path.index(nb)
            cycle = path[idx:] + [nb]
            cycles.append(cycle)
        elif nb not in seen:
            seen.add(nb)
            dfs(nb, path+[nb], pathset|{nb})
            # don't mark globally? keep
for f in files:
    if f not in seen:
        seen.add(f)
        dfs(f, [f], {f})
print("num cycles found (raw):", len(cycles))
for c in cycles[:20]:
    print(" -> ".join(os.path.basename(x) for x in c))
